import type { AppIcon } from "apps";

// Product mark from https://www.zohowebstatic.com/sites/zweb/images/productlogos/people.svg.
export const icons: readonly AppIcon[] = [
  {
    src: "data:image/png;base64,",
    mimeType: "image/png",
  },
];

import { accountRouter, defineApp, json, jsonSchema, mutation, query, router } from "apps";
import { always } from "apps/operations/approval";
import definitions from "./operations.json" with { type: "json" };
import { people } from "./provider.js";
import { createRequest } from "./request.js";
import { icons } from "./icon.js";

export default defineApp(
  { user: { accounts: { people: people.many() } }, icons },
  async ({ user, fetch, signal }) => ({
    tools: router(
      await accountRouter(
        user?.accounts.people ?? [],
        (account) => {
          const request = createRequest(account, fetch, signal);
          const groups = [...new Set(definitions.map((definition) => definition.area))];
          return router(
            Object.fromEntries(
              groups.map((area) => [
                area,
                router(
                  Object.fromEntries(
                    definitions
                      .filter((definition) => definition.area === area)
                      .map((definition) => {
                        const options = {
                          description: `${definition.description}\nReference: ${definition.documentation}`,
                          input: jsonSchema(definition.input),
                          output: json(),
                        };
                        const run = (_: unknown, input: Parameters<typeof request>[1]) =>
                          request(definition, input);
                        return [
                          definition.name,
                          definition.kind === "query"
                            ? query(options, run)
                            : mutation({ ...options, approval: always() }, run),
                        ];
                      }),
                  ),
                ),
              ]),
            ),
          );
        },
        { signal },
      ),
      {
        title: "Zoho People",
        description:
          "Forms, employees, attendance, shifts, leave, projects, jobs, clients, timesheets and time logs.",
        instructions:
          "Dates use your organization's date format unless the operation has a dateFormat parameter. IDs are strings. Structured query or form values are JSON encoded. Every write requires approval. Choose your Zoho data center before connecting. The app uses your account's own access and your organization's API limits.",
        icons,
      },
    ),
  }),
);

