{
  "name": "@signalbox/zoho-people",
  "description": "Zoho People employee records, forms, attendance, shifts, leave and time tracking.",
  "private": true,
  "type": "module",
  "executor": { "title": "Zoho People" },
  "dependencies": { "apps": "0.0.1-beta.104-basalt.9" }
}

import { defineProvider, oauth2, object, string } from "apps";
import { regions, peopleOrigin } from "./regions.js";
// The scope catalog uses forms.READ; two metadata pages contain the singular typo.
import scopes from "./scopes.json" with { type: "json" };
import { peopleResponse } from "./response.js";

const oauth = (region: keyof typeof regions) =>
  oauth2({
    authorizationUrl: `${regions[region].accounts}/oauth/v2/auth`,
    tokenUrl: `${regions[region].accounts}/oauth/v2/token`,
    revocationUrl: `${regions[region].accounts}/oauth/v2/token/revoke`,
    tokenEndpointAuthMethod: "client_secret_post",
    scopeSeparator: ",",
    scopes,
    authorizationParams: { access_type: "offline", prompt: "consent" },
    response: object({ access_token: string() }),
  });

export const people = defineProvider({
  name: "Zoho People",
  hosts: Object.values(regions).map((region) => new URL(region.api).host),
  auth: { oauthEu: oauth("oauthEu"), oauthUs: oauth("oauthUs"), oauthIn: oauth("oauthIn") },
  async health({ account, fetch, signal }) {
    const origin = peopleOrigin(account.method);
    await peopleResponse(
      await fetch(`${origin}/people/api/views`, {
        signal,
        headers: {
          Authorization: `Zoho-oauthtoken ${account.fields.access_token}`,
          Accept: "application/json",
        },
      }),
    );
    return { accountInfo: { displayName: `Zoho People (${regions[account.method].label})` } };
  },
});

export const regions = {
  oauthEu: {
    label: "Europe (EU)",
    accounts: "https://accounts.zoho.eu",
    api: "https://people.zoho.eu",
  },
  oauthUs: {
    label: "United States (US)",
    accounts: "https://accounts.zoho.com",
    api: "https://people.zoho.com",
  },
  oauthIn: {
    label: "India (IN)",
    accounts: "https://accounts.zoho.in",
    api: "https://people.zoho.in",
  },
} as const;

// Hosted OAuth metadata is sealed too, so the selected method owns every request's region.
export function peopleOrigin(method: keyof typeof regions) {
  return regions[method].api;
}

import type { AppContext, JsonValue, AccountOf } from "apps";
import { ProviderError } from "apps";
import type { people } from "./provider.js";
import { peopleOrigin } from "./regions.js";
import { peopleResponse } from "./response.js";

type Definition = {
  readonly method: string;
  readonly path: string;
  readonly encoding: string;
  readonly binary: boolean;
  readonly fixed: Readonly<Record<string, string>>;
};

const isObject = (value: JsonValue): value is Record<string, JsonValue> =>
  typeof value === "object" && value !== null && !Array.isArray(value);

const fields = (value: JsonValue | undefined): Record<string, JsonValue> => {
  if (value === undefined) return {};
  if (!isObject(value)) throw new ProviderError({ reason: "rejected" });
  return value;
};
const parameter = (value: JsonValue) => (typeof value === "string" ? value : JSON.stringify(value));
const decodeFile = (value: JsonValue) => {
  const file = fields(value);
  if (
    typeof file.dataBase64 !== "string" ||
    typeof file.filename !== "string" ||
    (file.contentType !== undefined && typeof file.contentType !== "string")
  )
    throw new ProviderError({ reason: "rejected" });
  const bytes = Uint8Array.from(atob(file.dataBase64), (character) => character.charCodeAt(0));
  return {
    blob: new Blob([bytes], { type: file.contentType ?? "application/octet-stream" }),
    name: file.filename,
  };
};

export function createRequest(
  account: AccountOf<typeof people>,
  fetch: AppContext["fetch"],
  signal: AbortSignal,
) {
  return async (definition: Definition, value: JsonValue) => {
    const input = fields(value);
    const path = { ...fields(input.path), ...definition.fixed };
    const pathname = definition.path.replace(/\{([^}]+)\}/g, (_, name: string) => {
      const part = path[name];
      if (typeof part !== "string" || part.length === 0)
        throw new ProviderError({ reason: "rejected" });
      return encodeURIComponent(part);
    });
    const origin = peopleOrigin(account.method);
    const url = new URL(`/people${pathname}`, origin);
    for (const [name, value] of Object.entries(fields(input.query)))
      url.searchParams.set(name, parameter(value));
    const headers = new Headers({
      Authorization: `Zoho-oauthtoken ${account.fields.access_token}`,
      Accept: "application/json",
    });
    const bodyFields = fields(input.body);
    let body: BodyInit | undefined;
    if (definition.encoding === "multipart" || input.files !== undefined) {
      const form = new FormData();
      for (const [name, value] of Object.entries(bodyFields)) form.set(name, parameter(value));
      for (const [name, value] of Object.entries(fields(input.files))) {
        const file = decodeFile(value);
        form.set(name, file.blob, file.name);
      }
      body = form;
    } else if (definition.encoding === "form") {
      const form = new URLSearchParams();
      for (const [name, value] of Object.entries(bodyFields)) form.set(name, parameter(value));
      headers.set("Content-Type", "application/x-www-form-urlencoded");
      body = form.toString();
    } else if (definition.encoding === "json") {
      headers.set("Content-Type", "application/json");
      body = JSON.stringify(bodyFields);
    }
    return peopleResponse(
      await fetch(url.href, { method: definition.method, headers, body, signal }),
      definition.binary,
    );
  };
}

import { json, ProviderError } from "apps";

const object = (value: unknown): value is Record<string, unknown> =>
  typeof value === "object" && value !== null && !Array.isArray(value);

/** Zoho reports both legacy status:1 and v3 status:error failures with HTTP 200. */
export async function peopleResponse(response: Response, binary = false) {
  if (!response.ok) {
    const reason =
      response.status === 401
        ? "unauthorized"
        : response.status === 429
          ? "rate_limited"
          : response.status >= 500
            ? "unavailable"
            : "rejected";
    throw new ProviderError({ reason, status: response.status });
  }
  if (binary && !response.headers.get("content-type")?.includes("json")) {
    const bytes = new Uint8Array(await response.arrayBuffer());
    let text = "";
    for (let offset = 0; offset < bytes.length; offset += 8192)
      text += String.fromCharCode(...bytes.subarray(offset, offset + 8192));
    return {
      contentType: response.headers.get("content-type") ?? "application/octet-stream",
      contentDisposition: response.headers.get("content-disposition"),
      dataBase64: btoa(text),
    };
  }
  const data: unknown = await response.json();
  const envelope = object(data) && object(data.response) ? data.response : data;
  if (
    object(envelope) &&
    (envelope.status === 1 ||
      envelope.status === "1" ||
      envelope.status === "error" ||
      envelope.status === "failure" ||
      envelope.status === "failed" ||
      envelope.error !== undefined ||
      envelope.errors !== undefined)
  )
    throw new ProviderError({ reason: "rejected", status: response.status });
  return json().parse(data);
}
